  "      var placements = placementList(snap);",
  "      var i;",
  "      for (i = 0; i < placements.length; i += 1) {",
  "        var end = Number(placements[i].start_bar) + Number(placements[i].bars);",
  "        if (Number.isFinite(end)) bars = Math.max(bars, Math.round(end) + TIMELINE_TAIL_BARS);",
  "      }",
  "      var sections = sectionList(snap);",
  "      for (i = 0; i < sections.length; i += 1) {",
  "        var sectionEnd = Number(sections[i].end_bar);",
  "        if (Number.isFinite(sectionEnd)) bars = Math.max(bars, Math.round(sectionEnd) + TIMELINE_TAIL_BARS);",
  "      }",
  "      var markers = markerList(snap);",
  "      for (i = 0; i < markers.length; i += 1) {",
  "        var at = Number(markers[i].bar);",
  "        if (Number.isFinite(at)) bars = Math.max(bars, Math.round(at) + TIMELINE_TAIL_BARS);",
  "      }",
  "      return clamp(bars, TIMELINE_MIN_BARS, TIMELINE_MAX_BARS);",
  "    }",
  "",
  "    function barPercent(bar, bars) {",
  "      var total = Number(bars) > 0 ? Number(bars) : TIMELINE_MIN_BARS;",
  "      var share = (Number(bar) / total) * 100;",
  "      return String(Math.round(share * 1000) / 1000) + '%';",
  "    }",
  "",
  "    // The lane column's width at this zoom: the bars times the base spacing,",
  "    // scaled, with the fixed header column beside it. The timeline root carries",
  "    // it, so the grid's lane column (and the ruler under it) IS that width and",
  "    // the host scrolls it sideways. Nothing here reaches the song or the",
  "    // engine.",
  "    function timelineWidthPx(bars) {",
