  "      var share = (Number(clientX) - Number(box.left)) / width;",
  "      return clamp(Math.floor(share * total), 0, total - 1);",
  "    }",
  "",
  "    // The bar a dragged playhead stands on, at beat resolution: a seek reads a",
  "    // bar in quarter bars, so a drag can leave the playhead between two lines.",
  "    function beatBarAtX(box, clientX, bars) {",
  "      var width = Number(box && box.width);",
  "      var total = Number(bars) > 0 ? Number(bars) : TIMELINE_MIN_BARS;",
  "      if (!(width > 0)) return 0;",
  "      var share = ((Number(clientX) - Number(box.left)) / width) * total;",
  "      var snapped = Math.round(share / BAR_BEAT_STEP) * BAR_BEAT_STEP;",
  "      return clamp(snapped, 0, total - 1);",
  "    }",
  "",
  "    function boxOf(node) {",
  "      if (!node || typeof node.getBoundingClientRect !== 'function') return null;",
  "      var box = node.getBoundingClientRect();",
  "      if (!box || !(Number(box.width) > 0)) return null;",
  "      return box;",
  "    }",
  "",
  "    function laneBox(trackId) {",
  "      var lane = view.lanes[String(trackId)];",
  "      return lane ? boxOf(lane.node) : null;",
  "    }",
  "",
  "    // The lane a dropped clip lands on, from the boxes the lanes were drawn",
  "    // with: the only thing a drop needs to know.",
  "    function laneAtPoint(clientX, clientY) {",
  "      for (var id in view.lanes) {",
