  "      }",
  "      return null;",
  "    }",
  "",
  "    function playheadNode() {",
  "      var line = el('div', 'st-tl-playhead');",
  "      line.setAttribute('data-role', 'playhead');",
  "      line.style.left = barPercent(view.playhead, view.timelineBars);",
