  "    function laneFor(snap, track, target) {",
  "      var id = String(track && track.id !== undefined && track.id !== null ? track.id : '');",
  "      var entry = view.armed && view.armed[id] ? view.armed[id] : null;",
  "      var targetId = target && target.id !== undefined && target.id !== null ? String(target.id) : '';",
  "      var armed = entry !== null;",
