  "        plan.setAttribute('data-role', 'rec-plan-row');",
  "        for (var at = 0; at < planned.length; at += 1) plan.appendChild(recLaneBand(planned[at], bars));",
  "        body.appendChild(plan);",
  "      }",
  "      var strip = el('div', 'st-rec-bars');",
  "      strip.setAttribute('data-role', 'rec-bar-ruler');",
