  "      body.appendChild(recLanesPlayheadNode());",
  "      row.appendChild(body);",
  "      return row;",
  "    }",
  "",
  "    // One of the plan's blocks as a band under the ruler: the same whole bars and",
  "    // the same label the scene plan widget lists, placed by the ruler's own bar",
  "    // scale. It is a picture, so a press goes through it.",
  "    function recLaneBand(block, bars) {",
  "      var start = Math.max(0, Math.round(Number(block && block.start_bar) || 0));",
  "      var end = Math.max(start + 1, Math.round(Number(block && block.end_bar) || start + 1));",
  "      var label = String((block && block.label) || 'Scene');",
  "      var band = el('div', 'st-lane-band', label);",
  "      band.setAttribute('data-role', 'rec-lane-band');",
  "      band.setAttribute('title', label + ', bars ' + String(start + 1) + ' to ' + String(end));",
  "      band.style.left = barPercent(start, bars);",
  "      band.style.width = barPercent(end - start, bars);",
  "      return band;",
  "    }",
  "",
  "    function recSectionBand(section, bars) {",
  "      var start = Math.max(0, Math.round(Number(section && section.start_bar) || 0));",
  "      var end = Math.max(start + 1, Math.round(Number(section && section.end_bar) || start + 1));",
  "      var band = el('div', 'st-rec-section', String((section && section.name) || 'Section'));",
  "      band.setAttribute('data-role', 'rec-section');",
