  "    }",
  "",
  "    // One track's lane. The header is the track's own controls; the body is its",
  "    // blocks and, on the record target, where it listens and what it hears.",
  "    function recLane(snap, track, index, bars, target) {",
  "      var lane = laneFor(snap, track, target);",
  "      var row = el('div', 'st-rec-row st-rec-lane'",
  "        + (lane.armed ? ' st-rec-lane-armed' : '')",
  "        + (lane.target ? ' st-rec-lane-target' : ''));",
  "      row.setAttribute('data-role', 'rec-lane');",
  "      row.setAttribute('data-track-id', lane.id);",
  "",
  "      var head = el('div', 'st-rec-side st-rec-lane-head');",
  "      var colour = el('span', 'st-rec-color');",
  "      colour.style.background = lane.colour;",
  "      head.appendChild(colour);",
  "      var box = el('div', 'st-rec-lane-name');",
  "      box.appendChild(el('span', 'st-rec-lane-title', lane.name));",
  "      box.appendChild(el('span', 'st-rec-lane-kind', lane.kind));",
  "      head.appendChild(box);",
  "      if (lane.armed) {",
  "        var chip = el('span', 'st-rec-armed-chip', REC_LANES_ARMED_TEXT);",
  "        chip.setAttribute('data-role', 'rec-armed');",
  "        head.appendChild(chip);",
  "      }",
  "      var acts = el('div', 'st-rec-acts');",
  "      var arm = button('st-toggle st-rec-arm' + (lane.armed ? ' st-on' : ''), lane.armLabel, {",
  "        'data-act': 'arm-audio',",
  "        'data-track-id': lane.id,",
  "        'aria-pressed': lane.armed ? 'true' : 'false',",
