  "      acts.appendChild(button('st-toggle' + (track && track.mute ? ' st-on' : ''), 'M', {",
  "        'data-act': 'mute', 'data-track-id': lane.id, 'aria-label': 'Mute ' + lane.name",
  "      }));",
  "      acts.appendChild(button('st-toggle' + (track && track.solo ? ' st-on' : ''), 'S', {",
