  "      head.appendChild(acts);",
  "      row.appendChild(head);",
  "",
  "      var body = el('div', 'st-rec-lane-body');",
  "      body.setAttribute('data-role', 'rec-lane-body');",
  "      body.style.backgroundImage = 'repeating-linear-gradient(to right, #1F2226 0 1px, transparent 1px '",
  "        + barPercent(1, bars) + ')';",
