  "      for (var i = 0; i < placements.length; i += 1) {",
  "        if (String(placements[i].track_id) !== lane.id) continue;",
  "        body.appendChild(recLanesBlock(snap, placements[i], bars));",
  "      }",
  "      if (lane.target) {",
  "        // The punch range is drawn over the clip's own beats, on the lane the",
  "        // take lands on, and that lane's body is where a drag sets another one:",
