  "        ? api.sourceLabel(entry, index)",
  "        : String(entry.label || ('input ' + String(Number(index) + 1)));",
  "      var source = el('span', 'st-rec-source', sourceText);",
  "      source.setAttribute('data-role', 'rec-source');",
  "      box.appendChild(source);",
  "      var monitorOn = !!(view.monitor && view.monitor.track_id === lane.id && view.monitor.on === true);",
  "      var chainText = api && typeof api.chainLabel === 'function' ? api.chainLabel(snap, lane.id, monitorOn) : '';",
  "      if (chainText) {",
  "        var chain = el('span', 'st-rec-chain', chainText);",
  "        chain.setAttribute('data-role', 'rec-chain');",
  "        box.appendChild(chain);",
  "      }",
