  "      var track = el('span', 'st-rec-meter-track');",
  "      var fill = el('span', 'st-rec-meter-fill');",
  "      fill.setAttribute('data-role', 'rec-meter-fill');",
  "      fill.style.width = '0%';",
  "      track.appendChild(fill);",
  "      meter.appendChild(track);",
  "      var peak = el('span', 'st-rec-peak', meterLevelText(state.peak_db));",
  "      peak.setAttribute('data-role', 'rec-peak');",
  "      meter.appendChild(peak);",
