  "      var drag = {",
  "        kind: 'fade',",
  "        id: String(placement.id),",
  "        side: side,",
  "        other: side === 'in' ? Number(placement.fade_out_beats) || 0 : Number(placement.fade_in_beats) || 0,",
  "        base: base,",
