  "",
  "    // A double-click on a marker or a section renames it, and so does its own",
  "    // button: both are named, and both names are the document's.",
  "    function onDoubleClick(event) {",
  "      var target = event.target && event.target.closest ? event.target.closest('[data-marker-id], [data-section-id], [data-act=pick-pattern]') : null;",
  "      if (!target) return;",
  "      if (target.getAttribute('data-act') === 'pick-pattern') { renamePattern(target); return; }",
  "      var markerId = target.getAttribute('data-marker-id');",
  "      if (markerId) { renameMarker(markerId); return; }",
  "      var sectionId = target.getAttribute('data-section-id');",
  "      if (sectionId) renameSection(sectionId);",
  "    }",
  "",
  "    // A pattern's name, typed into its own tab.",
