  "      if (!pattern) return;",
  "      inlineEdit(node, String(pattern.name || ''), function (value) {",
  "        send('pattern.rename', { clip_id: String(clip.id), pattern_id: String(pattern.id), name: value });",
  "      });",
  "    }",
  "",
  "    // The name the operator types for a marker or a section, or an empty string",
  "    // when the prompt was let go of, left empty or left unchanged.",
  "    function askName(question, current) {",
  "      var answer = null;",
  "      try { answer = window.prompt(question, current); }",
  "      catch (err) { answer = null; }",
  "      var name = answer === null || answer === undefined ? '' : String(answer).trim();",
  "      if (!name || name === current) return '';",
  "      return name;",
  "    }",
  "",
  "    function renameMarker(markerId) {",
  "      var marker = arrangementOf(snapshot()).markers[String(markerId)];",
  "      if (!marker) return;",
  "      var name = askName('What should the marker say?', String(marker.name || ''));",
  "      if (!name) return;",
  "      send('marker.rename', { id: String(markerId), name: name });",
  "    }",
  "",
  "    function renameSection(sectionId) {",
  "      var section = arrangementOf(snapshot()).sections[String(sectionId)];",
  "      if (!section) return;",
  "      var name = askName('What should the section say?', String(section.name || ''));",
  "      if (!name) return;",
  "      send('section.set', { id: String(sectionId), name: name });",
  "    }",
  "",
  "    // A removal the operator has to say yes to first (the browser's own",
  "    // question); a browser without one just goes ahead.",
  "    function confirmAction(text, run) {",
  "      var ask = true;",
  "      if (typeof window.confirm === 'function') ask = window.confirm(text);",
  "      if (ask) run();",
  "    }",
  "",
  "    // ---- the takes lane ---------------------------------------------------",
  "    //",
  "    // An audio clip's editor is the takes lane: the comp bar that says which",
  "    // take plays over which beats, one row per recording, and this device's",
  "    // own copy of the audio. Keep, Discard, Restore and one clip.set_comp per",
