  "    // clearing the cache are local.",
  "",
  "    function clipLengthBeats(clip) {",
  "      var bars = Number(clip && clip.length_bars);",
  "      return (Number.isFinite(bars) && bars > 0 ? bars : 1) * BEATS_PER_BAR;",
  "    }",
  "",
  "    function compOf(clip) {",
  "      return clip && Array.isArray(clip.comp) ? clip.comp : [];",
  "    }",
  "",
  "    function beatText(value) {",
