  "    }",
  "",
  "    // A clip's takes, oldest first, each with the number the lane shows: takes",
  "    // are numbered 1.. by recorded_at, so take 1 is the first recording.",
  "    function takesOfClip(snap, clipId) {",
  "      var takes = snap && snap.takes && typeof snap.takes === 'object' ? snap.takes : {};",
  "      var list = [];",
  "      for (var id in takes) {",
  "        if (!Object.prototype.hasOwnProperty.call(takes, id)) continue;",
  "        var take = takes[id];",
  "        if (!take || take.clip_id !== clipId) continue;",
  "        list.push(take);",
  "      }",
  "      list.sort(function (a, b) {",
  "        var at = Date.parse(String(a.recorded_at || ''));",
  "        var bt = Date.parse(String(b.recorded_at || ''));",
  "        if (!isNaN(at) && !isNaN(bt) && at !== bt) return at - bt;",
  "        if (isNaN(at) !== isNaN(bt)) return isNaN(at) ? 1 : -1;",
  "        return String(a.id) < String(b.id) ? -1 : (String(a.id) > String(b.id) ? 1 : 0);",
  "      });",
  "      var entries = [];",
  "      for (var i = 0; i < list.length; i += 1) entries.push({ take: list[i], number: i + 1 });",
  "      return entries;",
  "    }",
  "",
  "    // A take's length as seconds: its frames over the rate it was recorded at.",
  "    function takeSeconds(take) {",
  "      var frames = Number(take && take.frames);",
  "      var rate = Number(take && take.rate);",
  "      if (!Number.isFinite(frames) || !Number.isFinite(rate) || rate <= 0) return '0.0 s';",
  "      return (frames / rate).toFixed(1) + ' s';",
