  "      lane.setAttribute('data-role', 'takes-lane');",
  "      lane.setAttribute('data-clip-id', clip.id);",
  "      if (track) lane.setAttribute('data-track-id', track.id);",
  "      var entries = takesOfClip(snap, clip.id);",
