  "      row.setAttribute('data-role', 'take');",
  "      row.setAttribute('data-act', 'take-select');",
  "      row.setAttribute('data-clip-id', clip.id);",
  "      row.setAttribute('data-take-id', String(take.id));",
  "      row.setAttribute('data-take-n', String(entry.number));",
  "      row.setAttribute('title', 'Select this take, then drag on the comp bar to choose where it plays');",
  "",
  "      var swatch = el('span', 'st-take-color');",
  "      swatch.style.background = takeColor(entry.number);",
  "      row.appendChild(swatch);",
  "",
  "      var box = el('div', 'st-take-main');",
  "      box.appendChild(el('span', 'st-take-name', 'Take ' + String(entry.number)));",
  "      box.appendChild(el('span', 'st-take-meta', takeSeconds(take) + ' \u00b7 ' + String(take.author_label || 'Unknown')));",
  "      row.appendChild(box);",
  "",
  "      if (take.compensated !== true) {",
