  "      var picker = el('select', 'st-select st-roll-interval');",
  "      picker.setAttribute('data-act', 'roll-interval');",
  "      picker.setAttribute('aria-label', 'ROLL interval');",
  "      for (var at = 0; at < ROLL_INTERVALS.length; at += 1) {",
  "        var option = el('option', '', ROLL_INTERVALS[at]);",
  "        option.value = ROLL_INTERVALS[at];",
  "        if (String(view.roll.interval) === ROLL_INTERVALS[at]) option.selected = true;",
  "        picker.appendChild(option);",
  "      }",
  "      row.appendChild(picker);",
  "      row.appendChild(button('st-toggle st-pad-pause' + (view.padPaused === true ? ' st-on' : ''),",
  "        HOLD_PAUSE_TEXT, {",
  "          'data-act': 'pad-pause',",
  "          'aria-pressed': view.padPaused === true ? 'true' : 'false',",
  "          title: 'Freeze everything the pads are playing; press again to let it go'",
  "        }));",
  "      row.appendChild(el('p', 'st-pad-note st-pad-bar-note', HOLD_BAR_HINT));",
  "      row.appendChild(el('p', 'st-pad-note st-pad-bar-note', ROLL_BAR_HINT));",
  "      row.appendChild(padModeRow());",
  "      row.appendChild(padSensePopover());",
  "      return row;",
  "    }",
  "",
  "    // The mode toggle and the two chromatic pickers, on the live bar (C5b-2):",
  "    // what the grid plays, and the scale and key it walks when it is chromatic.",
  "    // Every one of them is this device's own choice - kept in its storage, never",
  "    // in the song - and each is a 44 px target that never selects its label.",
  "    function padModeRow() {",
  "      var box = el('div', 'st-pad-modes');",
  "      box.setAttribute('role', 'group');",
  "      box.setAttribute('aria-label', 'Pad mode');",
  "      for (var at = 0; at < PAD_MODE_LABELS.length; at += 1) {",
  "        var name = PAD_MODE_LABELS[at][0];",
  "        var on = padModeIs(name);",
  "        box.appendChild(button('st-toggle st-pad-mode' + (on ? ' st-on' : ''), PAD_MODE_LABELS[at][1], {",
  "          'data-act': 'pad-mode',",
  "          'data-mode': name,",
  "          'aria-pressed': on ? 'true' : 'false',",
  "          title: padModeTitle(name)",
  "        }));",
  "      }",
  "      box.appendChild(padChoice('pad-scale', 'Chromatic scale', PAD_SCALE_LABELS, view.padMode.scale));",
  "      box.appendChild(padChoice('pad-key', 'Chromatic key', padKeyOptions(), String(view.padMode.key)));",
  "      return box;",
  "    }",
  "",
  "    function padModeTitle(name) {",
  "      if (name === 'chromatic') return 'Play the selected pad across the scale and key';",
  "      if (name === 'velocity') return 'Sixteen pads, sixteen levels of the selected sample: the last pad is the loudest';",
  "      return 'Each pad plays its own sound';",
  "    }",
  "",
  "    /** One labelled picker, its options as pairs of the stored value and its text. */",
  "    function padChoice(act, label, options, value) {",
  "      var picker = el('select', 'st-select st-pad-choice');",
  "      picker.setAttribute('data-act', act);",
  "      picker.setAttribute('aria-label', label);",
  "      for (var at = 0; at < options.length; at += 1) {",
  "        var option = el('option', '', options[at][1]);",
  "        option.value = options[at][0];",
  "        if (String(value) === String(options[at][0])) option.selected = true;",
  "        picker.appendChild(option);",
  "      }",
  "      return picker;",
  "    }",
  "",
  "    /** The twelve keys, as the picker's own pairs. */",
  "    function padKeyOptions() {",
  "      var options = [];",
  "      for (var at = 0; at < PAD_KEY_NAMES.length; at += 1) {",
  "        options.push([String(at), PAD_KEY_NAMES[at]]);",
  "      }",
  "      return options;",
  "    }",
  "",
  "    // The sensitivity popover: the curve every press is shaped by, the level a",
  "    // press must reach to play at all, and the gain the curve ends at. A details",
  "    // element IS the popover, so nothing here opens or closes it by script, and a",
  "    // change is read when the next press comes rather than drawn again.",
  "    function padSensePopover() {",
  "      var sense = padSenseOf(view.padSense);",
  "      var details = el('details', 'st-pad-sense');",
  "      details.appendChild(el('summary', 'st-pad-sense-open', 'Sensitivity'));",
  "      var body = el('div', 'st-pad-sense-body');",
  "      body.appendChild(padChoice('pad-sense-curve', 'Velocity curve', PAD_SENSE_CURVE_LABELS, sense.curve));",
  "      body.appendChild(padSenseRange('pad-sense-threshold', 'Threshold',",
  "        PAD_SENSE_LOWEST_THRESHOLD, PAD_SENSE_HIGHEST_THRESHOLD, 1, sense.threshold));",
  "      body.appendChild(padSenseRange('pad-sense-gain', 'Gain',",
  "        PAD_SENSE_LOWEST_GAIN, PAD_SENSE_HIGHEST_GAIN, 0.05, sense.gain));",
  "      details.appendChild(body);",
  "      return details;",
  "    }",
  "",
  "    function padSenseRange(act, label, low, high, step, value) {",
  "      var wrap = el('label', 'st-pad-range');",
  "      wrap.appendChild(el('span', '', label));",
  "      var input = el('input', 'st-pad-range-input');",
  "      input.type = 'range';",
  "      input.min = String(low);",
  "      input.max = String(high);",
  "      input.step = String(step);",
  "      input.value = String(value);",
  "      input.setAttribute('data-act', act);",
  "      wrap.appendChild(input);",
  "      return wrap;",
  "    }",
  "",
  "    // One mode chosen: the buttons on the page say which one plays and the choice",
  "    // goes to this device's storage. Nothing is drawn again here, so the popover",
  "    // and the keyboard keep what they had.",
  "    function setPadMode(name) {",
  "      var next = String(name || '');",
