  "      storePadMode();",
  "      padModePaint();",
  "    }",
  "",
  "    /** The mode buttons' pressed look, on the nodes already on the page. */",
  "    function padModePaint() {",
  "      var nodes = page.querySelectorAll('[data-act=pad-mode]');",
  "      for (var at = 0; at < nodes.length; at += 1) {",
  "        var on = String(nodes[at].getAttribute('data-mode') || '') === view.padMode.mode;",
  "        nodes[at].className = 'st-toggle st-pad-mode' + (on ? ' st-on' : '');",
  "        nodes[at].setAttribute('aria-pressed', on ? 'true' : 'false');",
  "      }",
  "    }",
  "",
  "    function setPadScale(name) {",
  "      var next = String(name || '');",
  "      if (PAD_SCALES.indexOf(next) < 0) return;",
  "      view.padMode.scale = next;",
  "      storePadMode();",
  "    }",
  "",
  "    function setPadKey(value) {",
  "      var number = Number(value);",
  "      if (!isFinite(number) || Math.floor(number) !== number) return;",
  "      if (number < 0 || number >= PAD_KEY_NAMES.length) return;",
  "      view.padMode.key = number;",
