  "      var names = [];",
  "      for (var lane in motion) {",
  "        if (!Object.prototype.hasOwnProperty.call(motion, lane)) continue;",
  "        if (lane.indexOf(prefix) !== 0) continue;",
  "        names.push(lane);",
  "      }",
  "      names.sort();",
  "      box.appendChild(el('span', 'st-motion-label', 'Motion'));",
  "      if (view.motion.armed === true) {",
  "        box.appendChild(button('st-toggle st-on', 'Rec', {",
  "          'data-act': 'motion-arm', 'aria-pressed': 'true',",
  "          title: 'Motion is recording; click to stop and write the take'",
  "        }));",
  "        box.appendChild(el('span', 'st-motion-rec',",
  "          view.motion.startBeats === null",
