  "      }",
  "      return box;",
  "    }",
  "",
  "    // The step sequencer's panel: the patterns and the loop, the selected pad's",
  "    // lane of steps (a page of them) and the chain.",
  "    function stepsPanel(snap, clip, track, bank, index) {",
  "      var box = el('div', 'st-steps');",
  "      var pattern = shownPatternOf(snap, clip);",
  "      var pageSize = stepPageSize();",
  "      var length = clamp(Math.round(Number(clip.length_steps) || STEP_PAGE), 1, STEP_PAGE * STEP_PAGES);",
  "      var pages = Math.max(1, Math.ceil(length / pageSize));",
  "      var followed = pageForPlayhead(snap, clip);",
  "      if (followed !== null && followed !== view.samplerPage) view.samplerPage = followed;",
  "      view.samplerPage = clamp(Math.round(Number(view.samplerPage) || 0), 0, pages - 1);",
  "      view.stepLoop = { length: length, step_beats: Number(clip.step_beats) || 0.25 };",
  "",
  "      var tabs = el('div', 'st-pattern-tabs');",
  "      var patterns = patternsOfClip(snap, clip.id);",
  "      for (var i = 0; i < patterns.length; i += 1) {",
  "        var on = !!(pattern && String(patterns[i].id) === String(pattern.id));",
  "        var tab = button('st-toggle' + (on ? ' st-on' : ''), patterns[i].name, {",
  "          'data-act': 'pick-pattern',",
