  "      if (chosen) {",
  "        var locks = chosen.locks && typeof chosen.locks === 'object' ? chosen.locks : {};",
  "        var names = [];",
  "        for (var lockName in locks) {",
  "          if (Object.prototype.hasOwnProperty.call(locks, lockName)) names.push(lockName);",
  "        }",
  "        var clear = button('st-btn st-small', 'Clear locks', {",
