  "      for (var gone in view.mix.marks) {",
  "        if (!Object.prototype.hasOwnProperty.call(view.mix.marks, gone)) continue;",
  "        if (Object.prototype.hasOwnProperty.call(seen, gone)) continue;",
  "        delete view.mix.faults[gone];",
  "        delete view.mix.loading[gone];",
  "        delete view.mix.loadingAt[gone];",
