  "      dot.style.background = AGENT;",
  "      box.appendChild(dot);",
  "      box.appendChild(el('p', 'st-mix-banner-text', mixPassText(pass)));",
  "      var running = !!(view.mix.pass && view.mix.pass.running === true);",
  "      var comparing = view.mix.compare.active === true;",
  "      var ab = button('st-btn st-small', comparing ? MIX_AB_AFTER_TEXT : MIX_AB_BEFORE_TEXT, {",
  "        'data-act': 'mix-ab',",
  "        title: comparing",
  "          ? 'Play the mix as it is now'",
  "          : 'Play the song as it was before this pass, without changing it'",
  "      });",
  "      ab.setAttribute('aria-pressed', comparing ? 'true' : 'false');",
  "      box.appendChild(ab);",
  "      var undo = button('st-btn st-small', running ? MIX_UNDOING_TEXT : MIX_UNDO_PASS_TEXT, {",
  "        'data-act': 'mix-undo-pass',",
  "        title: 'Take this pass back out of the mix, newest step first'",
  "      });",
  "      if (running) undo.disabled = true;",
  "      box.appendChild(undo);",
  "      if (view.mix.pass && view.mix.pass.stopped) {",
  "        var stopped = el('p', 'st-mix-stopped', String(view.mix.pass.stopped));",
  "        stopped.setAttribute('data-role', 'mix-stopped');",
  "        box.appendChild(stopped);",
  "      }",
  "      return box;",
  "    }",
  "",
  "    /** What the banner says the pass did: its steps' own summaries. */",
  "    function mixPassText(pass) {",
  "      var parts = [];",
  "      for (var i = 0; i < pass.entries.length && i < 3; i += 1) {",
  "        var summary = String(pass.entries[i].summary || '');",
  "        if (summary) parts.push(summary);",
  "      }",
  "      var text = parts.join('; ');",
  "      if (pass.entries.length > parts.length) {",
  "        text += ' and ' + String(pass.entries.length - parts.length) + ' more';",
  "      }",
  "      return MIX_PASS_PREFIX + text + MIX_PASS_SUFFIX;",
  "    }",
  "",
  "    // The sentence the plan fixed for an undo pass that ran into a step somebody",
  "    // changed after the pass: it names that step, and says the ones before it are",
  "    // undone.",
  "    function stoppedText(entryId) {",
  "      var at = indexOfEntry(String(entryId));",
