  "      if (!kinds.length) select.disabled = true;",
  "      return select;",
  "    }",
  "",
  "    function stripFader(strip, item) {",
  "      var value = Number(item && item.gain_db);",
  "      if (!Number.isFinite(value)) value = 0;",
  "      var isMaster = strip.kind === 'master';",
