  "      row.appendChild(el('span', 'st-send-name', name));",
  "      var input = el('input', 'st-mix-range');",
  "      input.type = 'range';",
  "      input.min = '-60';",
  "      input.max = '6';",
  "      input.step = '0.5';",
  "      input.value = String(level);",
  "      input.setAttribute('data-act', 'send-level');",
  "      input.setAttribute('data-track-id', trackId);",
  "      input.setAttribute('data-return-id', returnId);",
  "      input.setAttribute('aria-label', 'Send level from ' + String(track.name) + ' to ' + name);",
  "      row.appendChild(input);",
  "      row.appendChild(button('st-toggle st-mix-mini' + (send.pre === true ? ' st-on' : '')",
  "        , send.pre === true ? 'Pre' : 'Post', {",
  "        'data-act': 'send-pre',",
  "        'data-track-id': trackId,",
  "        'data-return-id': returnId,",
  "        'aria-pressed': send.pre === true ? 'true' : 'false',",
  "        title: send.pre === true ? 'This send is taken before the fader' : 'This send is taken after the fader'",
  "      }));",
  "      row.appendChild(el('span', 'st-mix-value', dbText(level)));",
  "      row.appendChild(button('st-toggle st-mix-mini st-danger', '\u00d7', {",
  "        'data-act': 'send-remove',",
  "        'data-track-id': trackId,",
  "        'data-return-id': returnId,",
