  "      latency.setAttribute('data-role', 'mix-latency');",
  "      box.appendChild(latency);",
  "      box.appendChild(el('p', 'st-mix-note', MIX_TARGET_NOTE));",
  "      return box;",
  "    }",
  "",
  "    function targetPicker(target) {",
  "      var lufs = Number(target.lufs);",
