  "        return ampEditor(box, snap, null);",
  "      }",
  "      if (!insert) {",
  "        box.hidden = true;",
  "        box.appendChild(el('p', 'st-empty-note', ''));",
  "        return box;",
  "      }",
  "      box.hidden = false;",
  "      box.setAttribute('data-insert-id', String(insert.id));",
  "      var head = el('div', 'st-mix-editor-head');",
  "      head.appendChild(el('h3', 'st-mix-sub', effectLabel(insert.kind)));",
  "      head.appendChild(el('span', 'st-mix-editor-where', chainName(snap, insert.owner)));",
  "      head.appendChild(button('st-btn st-small', 'Done', {",
