  "        fault.setAttribute('data-role', 'mix-editor-fault');",
  "        box.appendChild(fault);",
  "      }",
  "      var spec = effectSpecOf(insert.kind);",
  "      var params = spec && spec.params && typeof spec.params === 'object' ? spec.params : {};",
  "      var grid = el('div', 'st-mix-params');",
  "      for (var name in params) {",
  "        if (!Object.prototype.hasOwnProperty.call(params, name)) continue;",
  "        grid.appendChild(insertParam(insert, name, params[name]));",
