  "        send('insert.add', { id: target.id, owner: target.owner, kind: ampKind(), params: params });",
  "        view.mix.newAmp = null;",
  "        view.mix.editor = target.id;",
  "        render();",
  "        return;",
  "      }",
  "      send('insert.set', { id: target.id, params: params });",
  "      render();",
  "    }",
  "",
  "    // A starter sound goes into the song through the gateway's own route (dashboard",
  "    // session and CSRF, like a download): the person at the page is the one who",
  "    // adds it, and the entry that comes back is the one the amp names.",
  "    function addStarterSound(bundledId, done) {",
  "      if (view.mix.starterBusy) {",
  "        // A second pick while the first starter sound is still on its way: say",
  "        // what is happening, and draw the picker again from the song. A choice",
  "        // that was never applied must never look applied.",
  "        toast(MIX_AMP_STARTER_PENDING_TEXT);",
  "        render();",
  "        return;",
  "      }",
  "      view.mix.starterBusy = true;",
  "      render();",
  "      fetch(BUNDLED_API, {",
  "        method: 'POST',",
  "        credentials: 'same-origin',",
  "        headers: studioHeaders(true),",
  "        body: JSON.stringify({ song_id: activeSongId, bundled_id: String(bundledId) })",
  "      })",
  "        .then(readJson)",
  "        .then(function (body) {",
  "          var entry = body && body.entry ? body.entry : null;",
  "          if (!entry || !entry.id) throw new Error(MIX_AMP_STARTER_FAILED_TEXT);",
  "          view.mix.starterBusy = false;",
  "          done(entry);",
  "          render();",
  "        })",
  "        .catch(function (err) {",
  "          view.mix.starterBusy = false;",
  "          render();",
  "          toast(errorText(err));",
  "        });",
  "    }",
  "",
  "    // The file input the amp editor carries for its own kind: Task 12's upload,",
  "    // reached from the picker's last row instead of from the grid's corner.",
  "    function openAmpFile(act) {",
  "      var host = page.querySelector('[data-role=mix-editor]');",
  "      var input = host ? host.querySelector('[data-act=' + act + ']') : null;",
  "      if (input && typeof input.click === 'function') input.click();",
  "    }",
  "",
  "    // The credit line of a capture or a cabinet, from the song's library or, for a",
  "    // starter sound not yet added, from the bundle's own list.",
  "    function ampCreditOf(id) {",
  "      if (!id) return '';",
