  "      // pad's sound (nothing else), which is what a re-chop needs when a pad",
  "      // still plays a slice the new chop would drop.",
  "      if (act === 'clear-pad' && trackId) {",
  "        var clearTrack = trackOf(snap, trackId);",
  "        var clearBank = bankOf(snap, trackId, String(target.getAttribute('data-bank-id') || ''));",
  "        var clearIndex = Number(target.getAttribute('data-pad-index'));",
  "        if (!clearTrack || !clearBank || !Number.isInteger(clearIndex)) return;",
  "        confirmThen(target, function () {",
  "          send('pad.clear', { track_id: clearTrack.id, bank_id: clearBank.id, index: clearIndex });",
  "        });",
  "        return;",
  "      }",
  "      if (act === 'close-clip') {",
  "        view.selectedClipId = null;",
  "        view.pendingSelect = null;",
  "        view.selectedNote = -1;",
  "        sendFocus(null);",
  "        render();",
  "        return;",
  "      }",
  "      // The pattern tabs: the one being shown, a new one, and the one being",
  "      // shown taken out (after a yes, and refused when it is the last).",
  "      if (act === 'pick-pattern') {",
  "        var picked = String(target.getAttribute('data-pattern-id') || '');",
  "        // A click on the tab already shown changes nothing: no redraw, so a",
  "        // double-click and the Rename button keep the tab they started on.",
  "        if (!picked || picked === String(view.samplerPattern)) return;",
  "        // Another pattern ends a motion take: its points belong to the pattern",
  "        // that was on screen, and they are written as its lanes.",
  "        finishMotion();",
  "        view.pendingPattern = '';",
  "        view.samplerPattern = picked;",
  "        view.samplerPage = 0;",
  "        view.samplerStep = null;",
  "        render();",
  "        return;",
  "      }",
  "      if (act === 'rename-pattern' && clipId) {",
  "        var renameId = String(target.getAttribute('data-pattern-id') || '');",
  "        var renameTabs = page.querySelectorAll('[data-act=pick-pattern]');",
  "        for (var renameAt = 0; renameAt < renameTabs.length; renameAt += 1) {",
  "          if (String(renameTabs[renameAt].getAttribute('data-pattern-id')) !== renameId) continue;",
  "          renamePattern(renameTabs[renameAt]);",
  "          return;",
  "        }",
  "        return;",
  "      }",
  "      if (act === 'add-pattern' && clipId) {",
  "        var freshPattern = 'pt-' + uuid();",
  "        send('pattern.add', { id: freshPattern, clip_id: clipId });",
  "        // It is selected when the snapshot holds it, never before.",
  "        view.pendingPattern = freshPattern;",
  "        view.samplerPage = 0;",
  "        return;",
  "      }",
  "      if (act === 'remove-pattern' && clipId) {",
  "        var doomedPattern = String(target.getAttribute('data-pattern-id') || '');",
  "        confirmThen(target, function () {",
  "          send('pattern.remove', { clip_id: clipId, pattern_id: doomedPattern });",
  "        });",
  "        return;",
  "      }",
  "      // The step buttons, their pages, their locks, and the chain.",
  "      if (act === 'step-page') {",
  "        view.samplerPage = Math.max(0, Math.round(Number(target.getAttribute('data-page')) || 0));",
  "        render();",
  "        return;",
  "      }",
  "      if (act === 'step-lock-done') {",
  "        view.stepLock = null;",
  "        render();",
  "        return;",
  "      }",
  "      if (act === 'step') {",
  "        var stepLane = stepsTarget(snap);",
  "        var stepPosition = Number(target.getAttribute('data-at'));",
  "        if (!stepLane || !Number.isInteger(stepPosition)) return;",
  "        // The step that just took a lock is not toggled off by its own click.",
  "        if (view.swallowStepClick === stepPosition) { view.swallowStepClick = null; return; }",
