  "            && String(lockedStep.clip_id) === String(stepLane.clip.id)",
  "            && String(lockedStep.pattern_id) === String(stepLane.pattern.id)",
  "            && String(lockedStep.bank_id) === String(stepLane.bank.id)",
  "            && Number(lockedStep.index) === Number(stepLane.index);",
  "          view.stepLock = null;",
  "          if (sameStep) { render(); return; }",
  "        }",
  "        view.samplerStep = stepPosition;",
  "        send('step.toggle', {",
  "          clip_id: String(stepLane.clip.id), pattern_id: String(stepLane.pattern.id),",
  "          at: stepPosition, bank_id: String(stepLane.bank.id), index: stepLane.index",
  "        });",
  "        return;",
  "      }",
  "      if (act === 'step-clear-locks') {",
  "        var lockLane = stepsTarget(snap);",
  "        var lockPosition = Number(target.getAttribute('data-at'));",
  "        if (!lockLane || !Number.isInteger(lockPosition)) return;",
  "        send('step.clear_locks', {",
  "          clip_id: String(lockLane.clip.id), pattern_id: String(lockLane.pattern.id),",
  "          at: lockPosition, bank_id: String(lockLane.bank.id), index: lockLane.index",
  "        });",
  "        return;",
  "      }",
  "      if (act === 'chain-add' || act === 'chain-remove' || act === 'chain-left' || act === 'chain-right') {",
  "        var chainClip = patternClipOf(snap);",
  "        if (!chainClip) return;",
  "        chainEdit(snap, chainClip, target.getAttribute('data-chain-at'), act.slice(6),",
  "          target.getAttribute('data-chain-pattern-id'));",
  "        return;",
  "      }",
  "      // The chop editor: one chop by hits, or the pads filled from this one on.",
  "      if (act === 'chop-retry') {",
  "        var retrySample = sampleOf(snap, String(target.getAttribute('data-sample-id') || ''));",
  "        if (!retrySample) return;",
  "        delete view.chopReadErrors[String(retrySample.id)];",
  "        ensureSampleDecoded(retrySample);",
  "        renderSampler(snap);",
  "        return;",
  "      }",
  "      if (act === 'chop-hits') {",
  "        var hitsSample = sampleOf(snap, String(target.getAttribute('data-sample-id') || ''));",
  "        if (!hitsSample) return;",
  "        chopSample(hitsSample, {",
  "          op: 'hits', options: { sensitivity: clamp(Number(view.chopSensitivity) || 0, 0, 1) }",
  "        });",
  "        return;",
  "      }",
  "      if (act === 'chop-assign') {",
  "        var assignKit = shownKit(snap);",
  "        var assignSample = sampleOf(snap, String(target.getAttribute('data-sample-id') || ''));",
  "        if (!assignKit || !assignSample) return;",
  "        assignSlicesToPads(snap, assignKit.track, assignKit.bank, shownPadIndex(), assignSample);",
  "        return;",
  "      }",
  "      if (act === 'delete-note') { deleteSelectedNote(); return; }",
  "      if (act === 'rename-clip') return;",
  "",
  "      if (act === 'launch-scene') { launchSceneAt(sceneId); return; }",
  "",
  "      if (act === 'mute' || act === 'solo') {",
  "        var mixed = trackOf(snap, trackId);",
  "        if (!mixed) return;",
  "        var args = { track_id: trackId };",
  "        if (act === 'mute') args.mute = mixed.mute !== true;",
  "        else args.solo = mixed.solo !== true;",
  "        send('track.set_mix', args);",
  "        return;",
  "      }",
  "      if (act === 'lock' || act === 'unlock') {",
  "        send('track.' + act, { track_id: trackId });",
  "        return;",
  "      }",
  "",
  "      if (act === 'rename-track') {",
  "        // A rename starts on the header's own name, whichever control asked for",
  "        // it: both of them sit inside the header, itself carrying data-track-id.",
  "        var header = target.closest('.st-th');",
  "        var nameNode = header ? header.querySelector('.st-name') : null;",
  "        var renaming = trackOf(snap, trackId);",
  "        if (!nameNode || !renaming) return;",
  "        inlineEdit(nameNode, renaming.name, function (value) {",
  "          send('track.rename', { track_id: trackId, name: value });",
  "        });",
  "        return;",
  "      }",
  "      if (act === 'rename-scene') {",
