  "        // too, so a closest() on the id alone would stop at the pencil and",
  "        // find no name to open.",
  "        var sceneHeaderNode = target.closest('.st-scene') || target.closest('[data-scene-id]');",
  "        var sceneNode = sceneHeaderNode ? sceneHeaderNode.querySelector('.st-scene-name') : null;",
  "        var sceneValue = sceneNode ? sceneNode.textContent : '';",
  "        if (!sceneNode) return;",
  "        inlineEdit(sceneNode, sceneValue, function (value) {",
  "          send('scene.rename', { scene_id: sceneId, name: value });",
  "        });",
  "        return;",
  "      }",
  "      if (act === 'remove-track') {",
  "        confirmThen(target, function () { send('track.remove', { track_id: trackId }); });",
  "        return;",
  "      }",
  "      if (act === 'remove-scene') {",
  "        confirmThen(target, function () { send('scene.remove', { scene_id: sceneId }); });",
  "        return;",
  "      }",
  "      if (act === 'remove-clip') {",
  "        confirmThen(target, function () { send('clip.remove', { clip_id: clipId }); });",
  "        return;",
  "      }",
  "",
  "      // The mixer: a return, the agent's pass (A/B and Undo pass), a chip's",
  "      // editor, an effect's bypass or removal, a proposed amp's yes, a send's",
  "      // removal, and a strip's mute. Every one is one command, except A/B, which",
  "      // writes nothing.",
  "      if (act === 'mix-add-return') {",
  "        send('return.add', { id: 'ret-' + uuid(), name: 'Return ' + String(returnList(snap).length + 1) });",
  "        return;",
  "      }",
  "      if (act === 'mix-ab') { toggleCompare(); return; }",
  "      if (act === 'mix-undo-pass') { undoPass(); return; }",
  "      if (act === 'insert-close') { view.mix.editor = ''; view.mix.newAmp = null; render(); return; }",
  "      if (act === 'insert-chip') {",
  "        if (view.mix.swallowChipClick) { view.mix.swallowChipClick = false; return; }",
  "        view.mix.editor = String(target.getAttribute('data-insert-id') || '');",
  "        render();",
  "        return;",
  "      }",
  "      if (act === 'insert-accept') {",
  "        insertAccept(target);",
  "        return;",
  "      }",
  "      if (act === 'insert-bypass') {",
  "        var bypassId = String(target.getAttribute('data-insert-id') || '');",
  "        var bypassInsert = insertOf(snap, bypassId);",
  "        if (!bypassInsert) return;",
  "        send('insert.bypass', { id: bypassId, bypass: bypassInsert.bypass !== true });",
  "        return;",
  "      }",
  "      if (act === 'insert-remove') {",
  "        var doomedInsert = String(target.getAttribute('data-insert-id') || '');",
  "        if (!doomedInsert) return;",
  "        if (String(view.mix.editor) === doomedInsert) view.mix.editor = '';",
  "        send('insert.remove', { id: doomedInsert });",
  "        return;",
  "      }",
  "      if (act === 'send-remove') {",
  "        var sendTrack = String(target.getAttribute('data-track-id') || '');",
  "        var sendReturn = String(target.getAttribute('data-return-id') || '');",
  "        if (!sendTrack || !sendReturn) return;",
  "        send('send.set', { track_id: sendTrack, return_id: sendReturn, level_db: null });",
  "        return;",
  "      }",
  "      if (act === 'send-pre') { sendSendPre(target); return; }",
  "      if (act === 'mix-mute' || act === 'mix-solo') {",
  "        var mixOwner = String(target.getAttribute('data-owner') || '');",
  "        var mixReturn = returnOf(snap, String(target.getAttribute('data-return-id') || ''));",
  "        var mixTrack = trackOf(snap, String(target.getAttribute('data-track-id') || ''));",
  "        if (mixOwner.indexOf('return:') === 0) {",
  "          if (act === 'mix-mute' && mixReturn) send('return.set', { id: mixReturn.id, mute: mixReturn.mute !== true });",
  "          return;",
  "        }",
  "        if (!mixTrack) return;",
  "        var mixArgs = { track_id: mixTrack.id };",
